function renderLayers(){if(production){production.renderLayers();return;}$('layers').replaceChildren();for(const i of [...all()].reverse()){const row=document.createElement('div');row.className='layer'+(selection.includes(i)?' active':'')+(!i.visible?' hidden-layer':'')+(i.locked?' locked':'');row.dataset.uid=i.data.uid;const type=document.createElement('span');type.className='layer-type';type.innerHTML=icon(i.data.kind==='png'?'image':i instanceof P.PointText?'text':i instanceof P.Group?'group':'rect');const name=document.createElement('button');name.className='layer-name';name.textContent=i.data.label;name.title=i.data.label;name.onclick=e=>{if(i.locked){notify('Desbloqueie este objeto no cadeado para editar.');return;}if(!i.visible){notify('Mostre este objeto no olho para editar.');return;}setTool('select');setSelection(e.shiftKey?selection.includes(i)?selection.filter(x=>x!==i):[...selection,i]:[i]);};const eye=document.createElement('button');eye.setAttribute('aria-label',(i.visible?'Ocultar ':'Mostrar ')+i.data.label);eye.innerHTML=icon('eye');eye.onclick=()=>edit(()=>{i.visible=!i.visible;selection=selection.filter(x=>x!==i);});const lock=document.createElement('button');lock.setAttribute('aria-label',(i.locked?'Desbloquear ':'Bloquear ')+i.data.label);lock.innerHTML=icon(i.locked?'lock':'unlock');lock.onclick=()=>edit(()=>{i.locked=!i.locked;selection=selection.filter(x=>x!==i);});row.append(type,name,eye,lock);$('layers').append(row);}}
