function cleanSVG(text){const doc=new DOMParser().parseFromString(text,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')throw Error('Este arquivo não é um SVG válido.');const clean=DOMPurify.sanitize(text,{USE_PROFILES:{svg:true,svgFilters:true},FORBID_TAGS:['script','foreignObject','animate','animateMotion','animateTransform','set','a']});const root=new DOMParser().parseFromString(clean,'image/svg+xml').documentElement;for(const el of [root,...root.querySelectorAll('*')])for(const attr of [...el.attributes]){if((attr.localName==='href'&&!attr.value.startsWith('#')&&!/^data:image\/(png|jpeg|webp);base64,/i.test(attr.value))||(/url\(/i.test(attr.value)&&!/url\(\s*['"]?#/.test(attr.value)))el.removeAttributeNode(attr);}return root;}
function mm(raw,fallback){const match=String(raw||'').match(/^([\d.]+)\s*(mm|cm|in|pt|px)?$/);return match?Number(match[1])*({mm:1,cm:10,in:25.4,pt:25.4/72,px:25.4/96}[match[2]||'px']):fallback;}
async function importSVG(text,name){const original=new DOMParser().parseFromString(text,'image/svg+xml');const metadata=original.getElementById('recorte-project');if(metadata){try{const s=JSON.parse(metadata.textContent);if(validFile(s)){edit(()=>restore(s));fit();notify('Projeto recuperado com os objetos editáveis.');return;}if(s.objects){edit(()=>migrateLegacy(s));fit();return;}}catch{}}
 const safe=cleanSVG(text),vb=(safe.getAttribute('viewBox')||'').trim().split(/[ ,]+/).map(Number),width=mm(safe.getAttribute('width'),vb[2]||100),height=mm(safe.getAttribute('height'),vb[3]||100);if(width<=0||height<=0)throw Error('O SVG tem dimensões inválidas.');safe.removeAttribute('width');safe.removeAttribute('height');safe.querySelectorAll('metadata').forEach(e=>e.remove());const okay=edit(()=>{const i=P.project.importSVG(safe,{expandShapes:true,insert:true});if(!i||i.bounds.width===0||i.bounds.height===0){i?.remove();throw Error('O SVG não contém desenhos reconhecidos.');}art.addChild(i);const factor=Math.min(1,doc.page.w*.85/width,doc.page.h*.85/height);i.fitBounds(new P.Rectangle(0,0,width*factor,height*factor));i.position=pt(doc.page.w/2,doc.page.h/2);decorate(i,name||'SVG importado');selection=[i];});if(!okay)return;if(production)await production.preparePiece(active()[0]);notify('SVG importado com corte automático. O vetor original foi preservado.');}
function readDataURL(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file);});}
async function importImage(file){const data=await readDataURL(file);const image=new Image();image.src=data;await image.decode();if(image.naturalWidth*image.naturalHeight>45_000_000)throw Error('Use uma imagem de até 45 megapixels nesta versão.');const before=serialized();art.activate();const raster=new P.Raster(image);const width=Math.min(100,doc.page.w*.7,doc.page.h*.7*image.naturalWidth/image.naturalHeight),height=width*image.naturalHeight/image.naturalWidth;raster.scale(width/image.naturalWidth);raster.position=pt(doc.page.w/2,doc.page.h/2);const group=decorate(new P.Group([raster]),file.name);group.data.kind='png';group.data.cut={offset:0,removeWhite:false,includeHoles:true,join:'sharp',smoothing:.3};const canvas=document.createElement('canvas');canvas.width=32;canvas.height=32;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0,32,32);const pixels=ctx.getImageData(0,0,32,32).data;let transparent=false;for(let j=3;j<pixels.length;j+=4)if(pixels[j]<250){transparent=true;break;}if(!transparent){const corners=[0,31*4,31*32*4,(32*32-1)*4];const color=[0,1,2].map(k=>Math.round(corners.reduce((sum,i)=>sum+pixels[i+k],0)/4));group.data.cut.removeWhite=corners.every(i=>color.every((n,k)=>Math.abs(n-pixels[i+k])<24));group.data.cut.backgroundColor='#'+color.map(n=>n.toString(16).padStart(2,'0')).join('');}selection=[group];pushHistory(before);sync();persist();await tracePNG(group);notify('Imagem importada. Ajuste a linha de corte no painel à direita.');}
$('file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;setTool('select');try{if(file.size>60_000_000)throw Error('Use um arquivo de até 60 MB.');if(production&&await production.importFile(file))return;if(/\.(png|jpe?g|webp)$/i.test(file.name)||file.type.startsWith('image/')&&file.type!=='image/svg+xml')await importImage(file);else{const text=await file.text();if(/\.(recorte|json)$/i.test(file.name)){const s=JSON.parse(text);if(!validFile(s))throw Error('Este arquivo não é um projeto Recorte válido.');edit(()=>restore(s));fit();refreshPNGs();notify('Projeto aberto.');}else await importSVG(text,file.name);}}catch(error){notify('Não foi possível importar: '+error.message);}finally{e.target.value='';}};
for(const id of ['import-btn','welcome-import','open-btn'])$(id).onclick=()=>$('file-input').click();
async function refreshPNGs(){for(const group of all().filter(i=>i.data.kind==='png')){const raster=group.children.find(i=>i instanceof P.Raster);if(raster&&!raster.loaded)await new Promise(resolve=>{raster.onLoad=resolve;setTimeout(resolve,5000);});await tracePNG(group);}}
function exportSVG(onlyCuts=false){
 const root=document.createElementNS('http://www.w3.org/2000/svg','svg');root.setAttribute('xmlns','http://www.w3.org/2000/svg');root.setAttribute('width',doc.page.w+'mm');root.setAttribute('height',doc.page.h+'mm');root.setAttribute('viewBox',`0 0 ${doc.page.w} ${doc.page.h}`);
 if(!onlyCuts){const meta=document.createElementNS(root.namespaceURI,'metadata');meta.id='recorte-project';meta.textContent=serialized();root.append(meta);}
 const styleCut=item=>{for(const leaf of leaves(item)){leaf.fillColor=null;leaf.strokeColor=onlyCuts?'#000000':cutAppearance(doc.production?.cutAppearance).color;leaf.strokeWidth=.1;}};
 for(const i of all()){
  if(!i.visible)continue;
  if(onlyCuts&&i.data.kind==='png'){
   for(const cut of i.children.filter(c=>c.data.kind==='cut')){const clone=cut.clone({insert:false});clone.transform(cut.parent.globalMatrix);styleCut(clone);root.append(clone.exportSVG({asString:false,precision:5}));clone.remove();}
  }else{
   const clone=i.clone({insert:false});
   if(onlyCuts){for(const leaf of leaves(clone))if(leaf instanceof P.Raster)leaf.remove();styleCut(clone);}
   else{for(const leaf of leaves(clone))if(leaf instanceof P.Raster)leaf.visible=true;if(isVectorCut(i))styleCut(clone);if(i.data.kind==='png')for(const cut of clone.children.filter(c=>c.data.kind==='cut'))styleCut(cut);}
   root.append(clone.exportSVG({asString:false,precision:5}));clone.remove();
  }
 }
 let output=new XMLSerializer().serializeToString(root);if(!onlyCuts&&machineConfig(doc).enabled)output=addMarksToSVG(output,machineConfig(doc).whiteBorderMm??5,documentRegistration(doc).parameters,machineConfig(doc));return '<?xml version="1.0" encoding="UTF-8"?>\n'+output;
}
async function save(kind){try{if(kind!=='project'&&all().some(i=>i.data.pending)){notify('Aguarde o cálculo da linha antes de exportar.');return;}if(kind==='cut'&&all().some(i=>i.visible&&i.data.kind==='png'&&i.data.cutError)){notify('Ajuste as imagens sem contorno válido antes de exportar.');return;}const content=kind==='project'?serialized():exportSVG(kind==='cut');const name=doc.name.replace(/[<>:"/\\|?*]/g,'_')+(kind==='cut'?' - corte':'');if(window.desktop){const path=await window.desktop.saveFile({kind,content,name});if(path)notify(kind==='project'?'Projeto salvo com todos os objetos editáveis.':kind==='cut'?'Linhas de corte exportadas em tamanho real.':'SVG exportado.');}else{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:kind==='project'?'application/json':'image/svg+xml'}));a.download=name+(kind==='project'?'.recorte':'.svg');a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}}catch(e){notify('Não foi possível salvar: '+e.message);}}
$('save-btn').onclick=()=>save('project');$('export-btn').onclick=()=>save('svg');$('export-cut').onclick=()=>save('cut');
$('new-project').onclick=()=>{edit(()=>{generation++;clearNodes();art.removeChildren();doc={name:'Novo projeto',page:{w:210,h:297,preset:'a4'}};selection=[];});setTool('select');fit();notify('Página pronta. Ctrl+Z recupera o projeto anterior.');};$('project-name').onchange=e=>edit(()=>doc.name=e.target.value.trim()||'Meu projeto');
$('page-size').onchange=e=>{const presets={a4:[210,297],a3:[297,420],'12':[305,305],custom:[doc.page.w,doc.page.h]};const [w,h]=presets[e.target.value];edit(()=>doc.page={w,h,preset:e.target.value});fit();};for(const [id,key]of [['page-w','w'],['page-h','h']])$(id).onchange=e=>{const value=Number(e.target.value);if(!Number.isFinite(value)||value<10||value>2000){notify('Use uma medida entre 10 e 2000 mm.');sync();return;}edit(()=>{doc.page[key]=value;doc.page.preset='custom';});fit();};$('show-grid').onchange=()=>updateView();$('grid-step').onchange=()=>{const v=Number($('grid-step').value);$('grid-step').value=clamp(Number.isFinite(v)?v:5,.5,100);updateView();};
$('fit').onclick=fit;$('zoom-in').onclick=()=>zoomAt(1.2);$('zoom-out').onclick=()=>zoomAt(1/1.2);$('view-mode').onclick=()=>{cutOnly=!cutOnly;for(const i of all())for(const raster of leaves(i).filter(c=>c instanceof P.Raster))raster.visible=!cutOnly;$('view-mode').innerHTML=icon('eye')+`<span>${cutOnly?'Mostrar imagem':'Ver só o corte'}</span>`;paint();};
$('help-btn').onclick=()=>$('help').showModal();for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();
document.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea')||document.querySelector('dialog[open]'))return;const ctrl=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(e.code==='Space'){space=true;e.preventDefault();$('canvas').style.cursor='grab';return;}if(ctrl){if(['a','c','v','x','d','g','z','y','s','o'].includes(key))e.preventDefault();if(key==='a')setSelection(all().filter(i=>i.visible&&!i.locked));if(key==='c')copy();if(key==='v')paste();if(key==='x'){copy();remove();}if(key==='d')duplicate();if(key==='g')(e.shiftKey?ungroup:group)();if(key==='z')history(e.shiftKey?redo:undo,e.shiftKey?undo:redo);if(key==='y')history(redo,undo);if(key==='s')save('project');if(key==='o')$('file-input').click();return;}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}if(e.key==='Enter'&&penPath){finishPen(false);setTool('select');}if(e.key==='Escape'){if(penPath){penPath.remove();penPath=null;$('pen-actions').hidden=true;}setSelection([]);setTool('select');}if(key==='0')fit();const map={v:'select',a:'nodes',p:'pen',l:'line',r:'rect',e:'ellipse',s:'star',t:'text',h:'hand'};if(map[key])setTool(map[key]);const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(delta&&active().length){e.preventDefault();edit(()=>{for(const i of active())i.translate(pt(...delta).multiply(e.shiftKey?10:1));});}});
document.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;$('canvas').style.cursor='';}});window.addEventListener('blur',()=>{space=false;});
function migrateLegacy(old){generation++;art.removeChildren();art.activate();doc={name:old.name||'Projeto recuperado',page:old.page||{w:210,h:297,preset:'a4'}};for(const o of old.objects||[]){let i;if(o.type==='rect')i=new P.Path.Rectangle({rectangle:new P.Rectangle(o.x,o.y,o.w,o.h),radius:2});if(o.type==='ellipse')i=new P.Path.Ellipse(new P.Rectangle(o.x,o.y,o.w,o.h));if(o.type==='text'){i=new P.PointText({point:pt(o.x,o.y+(o.fontSize||10)),content:o.text||'',fontSize:o.fontSize||10,fontFamily:'Segoe UI'});i.data.fontId='segoe';}if(o.type==='import'){i=P.project.importSVG(cleanSVG(o.content),{expandShapes:true});i.fitBounds(new P.Rectangle(o.x,o.y,o.w,o.h));}if(!i)continue;i.fillColor=o.fill==='none'?null:o.fill;i.strokeColor=o.stroke;i.strokeWidth=o.strokeWidth||0;if(o.angle)i.rotate(o.angle,i.bounds.center);decorate(i,o.name);art.addChild(i);}selection=[];}
